import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 定义通用的物品结构，涵盖装备与消耗品的所有可能字段
const ItemSchema = z.object({
  名称: z.string(),
  品质: z.enum(['破旧', '普通', '精良', '稀有', '史诗', '传说']),
  标签: z.array(z.string()),
  描述: z.string(),
  属性: z.record(z.string(), z.coerce.number()).optional(),
  能力详情: z.record(z.string(), z.string()).optional(),
  可堆叠: z.boolean().optional(),
  数量: z.coerce.number().optional(),
});

// 定义通用的空槽位结构
const EmptySlot = z.literal('--');

export const Schema = z.object({
  user: z.object({
    基础属性: z.object({
      姓名: z.string().prefault('{{user}}'),
      种族: z.string().prefault('人类'),
      等级: z.coerce.number().prefault(1),
      经验值: z.coerce.number().prefault(0),
      源质点: z.coerce.number().prefault(100),
      自由属性点: z.coerce.number().prefault(0),
      法力底蕴: z.coerce.number().prefault(0),
      // === 跑团检定核心六维 ===
      力量: z.coerce.number().prefault(10),
      体质: z.coerce.number().prefault(10),
      敏捷: z.coerce.number().prefault(10),
      精神: z.coerce.number().prefault(10),
      // ⚠ 悟性与魅力绝对上限锁死为20
      悟性: z.coerce.number().transform(v => _.clamp(v, 0, 20)).prefault(10),
      魅力: z.coerce.number().transform(v => _.clamp(v, 0, 20)).prefault(10),
    }),

    衍生状态: z.object({
     生命值: z.string().prefault('100.00/100.00'),
      法力值: z.string().prefault('100/100'),
    }),

    // 装备系统
    装备: z.object({
      武器: z.union([EmptySlot, ItemSchema]).prefault('--'),
      副手: z.union([EmptySlot, ItemSchema]).prefault('--'),
      头部防具: z.union([EmptySlot, ItemSchema]).prefault('--'),
      上半身防具: z.union([EmptySlot, ItemSchema]).prefault({
        名称: "粗布衣",
        品质: "破旧",
        标签: ["防具", "上半身"],
        描述: "一件普通的粗布衣服，勉强能遮风挡雨。"
      }),
      下半身防具: z.union([EmptySlot, ItemSchema]).prefault({
        名称: "粗布裤",
        品质: "破旧",
        标签: ["防具", "下半身"],
        描述: "耐磨的裤子，适合新手四处奔波。"
      }),
      足部防具: z.union([EmptySlot, ItemSchema]).prefault('--'),
      特殊装备: z.record(z.string(), ItemSchema).prefault({}),
    }),

    // 成就系统
    成就: z.record(
      z.string().describe('成就名称'),
      z.object({
        名称: z.string(),
        达成状态: z.boolean().prefault(true),
        达成时间: z.string(),
        描述: z.string(),
        奖励: z.string().optional(),
      })
    ).prefault({}),

    // 任务系统
    任务: z.object({
      主线任务: z.record(
        z.string().describe('任务ID'),
        z.object({
          标题: z.string(),
          描述: z.string(),
          进度: z.string().prefault('0/1'),
          状态: z.enum(['进行中', '已完成', '失败']).prefault('进行中'),
          奖励: z.string(),
        })
      ).prefault({
        "Main_001": { 
          标题: "🎲 命运的初次抽卡", 
          描述: "在灵灵的指引下首次使用祈愿卷进行万象池抽奖。", 
          进度: "0/1", 
          状态: "进行中", 
          奖励: "源质点x50, 初级治疗药水x1, 穿越身份定制卡x1"
        }
      }),
      支线任务: z.record(
        z.string().describe('任务ID'),
        z.object({
          标题: z.string(),
          描述: z.string(),
          状态: z.enum(['未接取', '进行中', '已完成']).prefault('未接取'),
          奖励: z.string(),
        })
      ).prefault({}),
      突发任务: z.record(
        z.string().describe('任务ID'),
        z.object({
          类型: z.string().prefault('突发'),
          状态: z.enum(['新任务', '进行中', '已完成', '已失败']).prefault('新任务'),
          名称: z.string(),
          描述: z.string(),
          目标: z.record(z.string(), z.string()).optional(),
          奖励: z.string(),
          失败惩罚: z.string().optional(),
          时限: z.string().optional(),
        })
      ).prefault({}),
    }),

    // 随身空间系统
    随身空间: z.record(
      z.string().describe('物品名称'),
      z.object({
        名称: z.string(),
        品质: z.enum(['破旧', '普通', '精良', '稀有', '史诗', '传说']),
        标签: z.array(z.string()),
        描述: z.string(),
        可堆叠: z.boolean().optional(),
        数量: z.coerce.number().optional(),
        属性: z.record(z.string(), z.coerce.number()).optional(),
        能力详情: z.record(z.string(), z.string()).optional(),
      })
    ).prefault({
      常驻祈愿券: { 名称: "常驻祈愿券", 品质: "稀有", 标签: ["消耗品", "祈愿券"], 描述: "一张通往命运的门票，可以进行一次【万象池】抽奖。赌狗的万恶之源。", 可堆叠: true, 数量: 1 },
      劣质治疗药水: { 名称: "劣质治疗药水", 品质: "普通", 标签: ["消耗品", "药水"], 描述: "瞬间恢复20%HP，但味道像变质的苦瓜汁。", 可堆叠: true, 数量: 2 },
      干粮: { 名称: "干粮", 品质: "普通", 标签: ["消耗品", "食物"], 描述: "能填饱肚子的硬面包。坚硬程度堪比板砖。", 可堆叠: true, 数量: 3 }
    }),

    // 技能系统
    技能: z.record(
      z.string().describe('技能名称'),
      z.object({
        等级: z.string().prefault('Lv.1 入门'),
        熟练度: z.coerce.number().optional(),
        升级所需熟练度: z.coerce.number().optional(),
        描述: z.string(),
        能力详情: z.record(z.string(), z.string()).optional(),
        特殊消耗: z.string().optional(),
        进化途径: z.string().optional(),
      })
    ).prefault({
      数据化思维: {
        等级: "MAX",
        描述: "被动技能。精神已与系统同调，能看到系统面板与灵灵，兼容诸天万界基本的超凡体系。无消耗。"
      }
    }),
  }),

  // 系统后台数据
  系统: z.object({
    随身空间: z.object({
      容量: z.coerce.number().prefault(30),
    }),
    抽奖: z.object({
      常驻池保底: z.coerce.number().prefault(0),
      限定池保底: z.coerce.number().prefault(0),
    }),
    商城: z.object({
      上次刷新日期: z.string().prefault('0000-00-00'),
      商品列表: z.record(
        z.string().describe('商品名称'),
        z.object({
          品质: z.enum(['破旧', '普通', '精良', '稀有', '史诗', '传说']),
          标签: z.array(z.string()).prefault([]),
          价格: z.coerce.number(),
          描述: z.string(),
          属性: z.record(z.string(), z.coerce.number()).optional(),
          能力详情: z.record(z.string(), z.string()).optional(),
        })
      ).prefault({
        初级治疗药水: { 品质: "普通", 标签: ["消耗品", "药水"], 价格: 50, 描述: "瞬间恢复30%HP，味道像草莓。" },
        战术小刀: { 品质: "普通", 标签: ["武器", "匕首"], 价格: 100, 描述: "便于携带的近战武器。" },
        坚固的皮甲: { 品质: "精良", 标签: ["防具", "上半身"], 价格: 120, 描述: "能提供基础防护的鞣制皮甲。" },
        学徒法袍: { 品质: "精良", 标签: ["防具", "上半身"], 价格: 150, 描述: "绣有魔力纹路的法袍，能更好地引导法力流动。", 属性: { 精神: 2 } },
        闪光粉: { 品质: "普通", 标签: ["消耗品", "战术道具"], 价格: 30, 描述: "在敌人面前扔出有可能短暂致盲对方，创造逃跑或攻击的机会。" },
        常驻祈愿券: { 品质: "稀有", 标签: ["消耗品", "祈愿券"], 价格: 100, 描述: "一张通往命运的门票，用于【万象池】。单抽出奇迹！" }
      })
    })
  }),

  // 关系数据 (双轴情感)
  关系: z.record(
    z.string().describe('角色名称'),
    z.object({
      信赖: z.coerce.number().transform(v => _.clamp(v, -100, 100)).prefault(50),
      恋慕: z.coerce.number().transform(v => _.clamp(v, 0, 100)).optional(),
    })
  ).prefault({
    灵灵: { 信赖: 50 }
  }),

  // 世界状态
  世界: z.object({
    当前世界代号: z.string().prefault('数据虚空 (教学关卡)'),
    当前世界危险等级: z.string().prefault('绝对安全'),
    近期事务: z.string().prefault('宿主意识刚刚苏醒，面临灵灵的嘲讽'),
  })
});

$(() => {
  registerMvuSchema(Schema);
})

function loadFontAwesome() {
    if ($('link[href*="font-awesome"]').length > 0 || $('link[href*="fontawesome"]').length > 0) return;
    var link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css';
    link.crossOrigin = 'anonymous';
    document.head.appendChild(link);
}

var panelStyles = `
<style id="system-panel-styles">
@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@400;500;700;900&display=swap');
html, body { height: 100%; min-height: 100vh; margin: 0; padding: 0; }
:root { --sys-cyan:#00e5ff; --sys-cyan-dim:rgba(0,229,255,0.15); --sys-cyan-glow:rgba(0,229,255,0.4); --sys-panel:rgba(10,18,35,0.65); --sys-border:rgba(0,229,255,0.3); --sys-text:#f8fafc; --sys-text-dim:#94a3b8; --sys-accent:#fbbf24; --sys-red:#ef4444; --sys-green:#10b981; --q-trash:#94a3b8; --q-normal:#ffffff; --q-fine:#3b82f6; --q-rare:#a855f7; --q-epic:#fbbf24; --q-legend:#ef4444; }
#system-trigger-btn { position: fixed; top: 50%; right: 10px; transform: translateY(-50%); width: 42px; height: 42px; background: rgba(10, 18, 35, 0.7); backdrop-filter: blur(4px); border: 1px solid var(--sys-cyan); color: var(--sys-cyan); font-size: 18px; cursor: move; z-index: 10000; box-shadow: 0 0 15px var(--sys-cyan-dim); display: flex; align-items: center; justify-content: center; user-select: none; touch-action: none; padding: 0; border-radius: 50%; transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.3s, background 0.3s; }
#system-trigger-btn::after { content: ''; position: absolute; width: 30px; height: 30px; border: 1px solid rgba(0, 229, 255, 0.4); border-radius: 50%; border-top-color: transparent; border-bottom-color: transparent; animation: spin 3s linear infinite; }
@keyframes spin { 100% { transform: rotate(360deg); } }
#system-trigger-btn:hover { transform: translateY(-50%) scale(1.1); box-shadow: 0 0 25px var(--sys-cyan-glow); background: rgba(0, 229, 255, 0.15); color: #fff; }
#system-trigger-btn.dragging { transition: none !important; transform: none !important; cursor: grabbing; }
#system-panel-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 5, 15, 0.4); backdrop-filter: blur(8px); z-index: 9999; display: none; align-items: center; justify-content: center; animation: fadeIn 0.3s ease-out; }
#system-panel-overlay.active { display: flex; }
#system-panel-overlay.pinned { background: transparent; backdrop-filter: none; pointer-events: none; }
#system-panel-overlay.pinned .system-panel-frame { pointer-events: auto; }
@keyframes fadeIn { from { opacity: 0; backdrop-filter: blur(0); } to { opacity: 1; backdrop-filter: blur(8px); } }
.system-panel-frame { position: relative; width: 96%; max-width: 620px; height: 88%; max-height: 760px; background: var(--sys-panel); border: 1px solid var(--sys-border); border-radius: 8px; box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5), 0 0 20px rgba(0, 229, 255, 0.1); display: flex; flex-direction: row; font-family: 'Consolas', 'Microsoft YaHei', monospace; color: var(--sys-text); overflow: hidden; animation: uiBoot 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
@keyframes uiBoot { 0% { transform: scale(0.96) translateY(10px); opacity: 0; } 100% { transform: scale(1) translateY(0); opacity: 1; } }
.sys-sidebar { width: 68px; background: rgba(0, 0, 0, 0.3); border-right: 1px solid rgba(0, 229, 255, 0.15); display: flex; flex-direction: column; align-items: center; padding-top: 15px; flex-shrink: 0; z-index: 10; position: relative; overflow-y: auto; }
.sys-sidebar::-webkit-scrollbar { display: none; }
.nav-item { width: 100%; height: 58px; display: flex; flex-direction: column; align-items: center; justify-content: center; cursor: pointer; color: var(--sys-text-dim); transition: all 0.2s ease; position: relative; border-left: 3px solid transparent; flex-shrink: 0; }
.nav-item i { font-size: 16px; margin-bottom: 5px; transition: 0.2s; }
.nav-item span { font-size: 10px; font-weight: bold; letter-spacing: 1px; }
.nav-item:hover { color: #fff; background: rgba(255, 255, 255, 0.05); }
.nav-item.active { color: var(--sys-cyan); background: linear-gradient(90deg, rgba(0,229,255,0.1) 0%, transparent 100%); border-left: 3px solid var(--sys-cyan); }
.nav-item.active i { transform: scale(1.15); text-shadow: 0 0 10px var(--sys-cyan); }
.sys-main { flex: 1; display: flex; flex-direction: column; overflow: hidden; position: relative; z-index: 5; }
.sys-header { height: 45px; display: flex; align-items: center; justify-content: space-between; padding: 0 18px; background: linear-gradient(90deg, rgba(0, 229, 255, 0.05) 0%, transparent 100%); border-bottom: 1px solid rgba(0, 229, 255, 0.15); flex-shrink: 0; cursor: move; transition: 0.3s; }
.sys-title { font-size: 13px; font-weight: bold; color: var(--sys-cyan); letter-spacing: 1px; display: flex; align-items: center; gap: 6px; text-transform: uppercase; transition: 0.3s; white-space: nowrap;}
.sys-title::before { content: '◈'; color: var(--sys-cyan); font-size: 10px; transition: 0.3s; }
.header-controls { display: flex; gap: 12px; }
.ctrl-btn { background: rgba(255,255,255,0.05); border: 1px solid rgba(0, 229, 255, 0.3); color: var(--sys-cyan); width: 24px; height: 24px; border-radius: 4px; cursor: pointer; display: flex; justify-content: center; align-items: center; font-size: 12px; transition: 0.2s; }
.ctrl-btn:hover { background: var(--sys-cyan); color: #000; box-shadow: 0 0 10px var(--sys-cyan-glow); }
.ctrl-btn.pinned { color: #000; background: var(--sys-accent); border-color: var(--sys-accent); box-shadow: 0 0 10px rgba(251,191,36,0.5); }
.sys-header.edit-mode-active { background: linear-gradient(90deg, rgba(239, 68, 68, 0.15) 0%, transparent 100%); border-bottom-color: rgba(239, 68, 68, 0.4); }
.sys-title.edit-mode-active { color: var(--sys-red); }
.sys-title.edit-mode-active::before { content: '⚠️'; color: var(--sys-red); }
.ctrl-btn.edit-btn.active { color: #000; background: var(--sys-red); border-color: var(--sys-red); box-shadow: 0 0 10px rgba(239, 68, 68, 0.6); }
.sys-body { flex: 1; position: relative; overflow: hidden; }
.tab-pane { position: absolute; top: 0; left: 0; width: 100%; height: 100%; overflow-y: auto; padding: 15px; box-sizing: border-box; display: none; animation: tabFade 0.2s ease-out; }
.tab-pane.active { display: block; }
@keyframes tabFade { from { opacity: 0; transform: scale(0.98); } to { opacity: 1; transform: scale(1); } }
.tab-pane::-webkit-scrollbar { width: 3px; }
.tab-pane::-webkit-scrollbar-track { background: transparent; }
.tab-pane::-webkit-scrollbar-thumb { background: rgba(0, 229, 255, 0.3); border-radius: 3px; }

.panel-section { margin-bottom: 15px; background: rgba(255, 255, 255, 0.02); border: 1px solid rgba(0, 229, 255, 0.1); padding: 12px; position: relative; border-radius: 6px; }
.section-title { font-size: 11px; font-weight: bold; color: var(--sys-cyan); margin-bottom: 10px; display: flex; align-items: center; gap: 8px; text-transform: uppercase; letter-spacing: 1px; }

.interactive-item { cursor: pointer; transition: all 0.2s ease; border-radius: 4px; border: 1px solid transparent; }
.interactive-item:hover { background: rgba(0, 229, 255, 0.08) !important; border-color: rgba(0, 229, 255, 0.3); box-shadow: 0 4px 12px rgba(0, 229, 255, 0.05); }
.interactive-item:active { transform: scale(0.98); }
.data-row { display: flex; justify-content: space-between; font-size: 11px; margin-bottom: 8px; align-items: center; }
.data-label { color: var(--sys-text-dim); }
.data-val { color: #fff; font-weight: bold; }

/* 进度条弹性排版 */
.status-bar-wrapper { margin-bottom: 10px; display: flex; align-items: center; gap: 8px; }
.status-label { font-size: 10px; color: var(--sys-cyan); width: auto; min-width: 38px; flex-shrink: 0; font-weight: bold; letter-spacing: 1px; white-space: nowrap; margin-right: 4px; }
.status-track, .r-track { flex: 1; height: 3px; background: rgba(255, 255, 255, 0.08); border-radius: 2px; position: relative; overflow: visible; }
.status-track { margin: 0 4px; }
.r-track { margin: 0; }
.status-fill, .r-fill { height: 100%; transition: width 0.4s ease; max-width: 100%; position: relative; z-index: 1; border-radius: 2px; }
.status-fill::after, .r-fill::after { content: ''; position: absolute; right: -1px; top: -1px; width: 2px; height: 5px; background: rgba(255, 255, 255, 0.8); border-radius: 1px; z-index: 4; }

.hp-fill { background: #ef4444; box-shadow: 0 0 4px rgba(239, 68, 68, 0.3); } .hp-fill::after { box-shadow: 0 0 4px #ef4444; }
.mp-fill { background: #3b82f6; box-shadow: 0 0 4px rgba(59, 130, 246, 0.3); } .mp-fill::after { box-shadow: 0 0 4px #3b82f6; }
.exp-fill { background: #10b981; box-shadow: 0 0 4px rgba(16, 185, 129, 0.3); } .exp-fill::after { box-shadow: 0 0 4px #10b981; }
.fill-trust { background: var(--sys-green); box-shadow: 0 0 4px rgba(16, 185, 129, 0.3); } .fill-trust::after { box-shadow: 0 0 4px var(--sys-green); }
.fill-trust-negative { background: var(--sys-red); box-shadow: 0 0 4px rgba(239, 68, 68, 0.3); } .fill-trust-negative::after { box-shadow: 0 0 4px var(--sys-red); }
.fill-love { background: #ec4899; box-shadow: 0 0 4px rgba(236, 72, 153, 0.3); } .fill-love::after { box-shadow: 0 0 4px #ec4899; }

.status-val { font-size: 11px; color: #fff; width: auto; min-width: 45px; text-align: right; flex-shrink: 0; font-family: 'Orbitron', sans-serif; white-space: nowrap; margin-left: 4px; }

.attr-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.attr-box { background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.05); padding: 8px 2px; display: flex; flex-direction: column; align-items: center; border-radius: 4px; position: relative; }
.attr-name { font-size: 10px; color: var(--sys-text-dim); margin-bottom: 2px; letter-spacing: 1px; }
.attr-val { font-size: 14px; font-weight: bold; color: #fff; font-family: 'Orbitron', sans-serif; white-space: nowrap; }
.attr-tier { font-size: 9px; color: var(--sys-cyan); background: rgba(0,229,255,0.1); padding: 2px 4px; border-radius: 2px; margin-top: 4px; white-space: nowrap; transform: scale(0.85); font-weight: bold; text-align: center; }

.equip-human-container { position: relative; width: 100%; height: 300px; display: flex; justify-content: center; align-items: center; }
.human-silhouette { font-size: 190px; color: rgba(0, 229, 255, 0.1); position: absolute; z-index: 1; }
.eq-node { position: absolute; width: 36%; max-width: 120px; background: rgba(10, 18, 35, 0.8); border: 1px solid rgba(0, 229, 255, 0.2); padding: 8px; border-radius: 4px; z-index: 2; display: flex; flex-direction: column; backdrop-filter: blur(4px); }
.eq-node::before { content: ''; position: absolute; top: 50%; width: 25px; height: 1px; background: rgba(0, 229, 255, 0.3); z-index: -1; }
.eq-left::before { right: -25px; } .eq-right::before { left: -25px; }
.eq-pos-1 { top: 15%; left: 2%; } .eq-pos-2 { top: 15%; right: 2%; } 
.eq-pos-3 { top: 45%; left: 2%; } .eq-pos-4 { top: 45%; right: 2%; } 
.eq-pos-5 { top: 75%; left: 2%; } .eq-pos-6 { top: 75%; right: 2%; } 
.eq-type { font-size: 9px; color: var(--sys-cyan); margin-bottom: 3px; text-transform: uppercase; }
.eq-name { font-size: 11px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-weight: bold; }
