// ==== 【修仙级大数格式化】 ====
function formatNum(val) {
    var num = parseFloat(val);
    if (isNaN(num)) return val;
    var absNum = Math.abs(num);
    if (absNum < 10000) return (num % 1 !== 0) ? num.toFixed(2).replace(/\.?0+$/, '') : num.toString();

    var units = [
        { value: 1e44, symbol: '载' }, { value: 1e40, symbol: '正' },
        { value: 1e36, symbol: '涧' }, { value: 1e32, symbol: '沟' },
        { value: 1e28, symbol: '穰' }, { value: 1e24, symbol: '秭' },
        { value: 1e20, symbol: '垓' }, { value: 1e16, symbol: '京' },
        { value: 1e12, symbol: '兆' }, { value: 1e8,  symbol: '亿' },
        { value: 1e4,  symbol: '万' }
    ];
    for (var i = 0; i < units.length; i++) {
        if (absNum >= units[i].value) {
            var formatted = (num / units[i].value).toFixed(2).replace(/\.?0+$/, '');
            return formatted + units[i].symbol;
        }
    }
    return num.toString();
}

var formatBarText = function(str) {
    if (!str) return "0/0";
    var parts = String(str).split('/');
    if (parts.length === 2) return formatNum(parts[0]) + '/' + formatNum(parts[1]);
    return formatNum(str);
};

