    setTimeout(bindInteractiveEvents, 50);
}

function openModal(title, icon, contentHtml) {
    $('#sys-modal-title').html(`<i class="fas ${icon}"></i> ${title}`);
    $('#sys-modal-content').html(contentHtml);
    $('#sys-detail-modal').addClass('active');

    $('#sys-detail-modal .sys-action-btn').off('click').on('click', function() {
        var action = $(this).data('action');
        var path = $(this).data('path');
        if (action === 'del') {
            SysVarApi.del(path);
        } else if (action === 'save') {
            var isPrim = $(this).data('prim') === true || $(this).data('prim') === 'true';
            SysVarApi.saveForm(path, isPrim);
        } else if (action === 'save_with_rename') {
            var oldName = $(this).data('old');
            var newName = $('#edit-name-field').val().trim();
            var basePath = $(this).data('path');
            var parentPath = basePath.split('.').slice(0, -1).join('.');
            (async function() {
                var updates = [];
                $('.sys-edit-obj-field').each(function() {
                    var k = $(this).data('key'); var v = $(this).val();
                    if (!isNaN(v) && v.trim() !== '' && !v.includes('/')) v = Number(v); updates.push({k: k, v: v});
                });
                for (var i=0; i<updates.length; i++) { await SysVarApi.set(basePath + '.' + updates[i].k, updates[i].v); }
                if (newName && newName !== oldName) { await SysVarApi.renameKey(parentPath, oldName, newName); } 
                else { updatePanelData(); closeModal(); if (typeof window.SillyTavern !== 'undefined' && window.SillyTavern.getContext) { var ST = window.SillyTavern.getContext(); if (ST.eventSource && window.tavern_events && window.tavern_events.VARIABLES_UPDATED) ST.eventSource.emit(window.tavern_events.VARIABLES_UPDATED); } }
            })();
        } else if (action === 'save_multi') {
            var updates = [];
            $('.sys-edit-multi-field').each(function() {
                var p = $(this).data('path'); var v = $(this).val();
                if (!isNaN(v) && v.trim() !== '' && !v.includes('/')) v = Number(v); updates.push({p: p, v: v});
            });
            (async function() {
                for (var i=0; i<updates.length; i++) { await SysVarApi.set(updates[i].p, updates[i].v); }
                updatePanelData(); closeModal();
                if (typeof window.SillyTavern !== 'undefined' && window.SillyTavern.getContext) { var ST = window.SillyTavern.getContext(); if (ST.eventSource && window.tavern_events && window.tavern_events.VARIABLES_UPDATED) ST.eventSource.emit(window.tavern_events.VARIABLES_UPDATED); }
            })();
        }
    });
}

