                if (d.能力详情 && Object.keys(d.能力详情).length > 0) { html += `<div class="md-desc" style="border-color:var(--sys-accent); margin-top:10px;"><strong style="color:var(--sys-accent);">[招式与应用]</strong><br>`; for (var nk in d.能力详情) { html += `<span style="color:#fff; font-weight:bold;">◈ ${nk}</span><br><span style="color:#cbd5e1; font-size:10px;">${d.能力详情[nk]}</span><br><br>`; } html += `</div>`; }
                if (d.进化途径) html += `<div class="md-desc" style="border-color:var(--q-rare); margin-top:10px;"><strong style="color:var(--q-rare);">[终极进化途径]</strong><br>${d.进化途径}</div>`;
            }
            else if (info.type === 'quest') {
                var d = info.data; title = d.标题 || d.名称 || '未知任务'; icon = 'fa-tasks'; var getC = (v) => SysVarApi.isMvuTupleLeafValue(v) ? v[0] : v;
                var statusColor = getC(d.状态) === '已完成' ? '#10b981' : (getC(d.状态) === '已失败' ? '#ef4444' : '#fbbf24');
                html += `<div class="md-row"><span class="md-label">任务类型:</span> <span class="md-tag" style="background:rgba(255,255,255,0.1); border:none;">${info.qtype}</span></div><div class="md-row"><span class="md-label">当前状态:</span> <span class="md-val" style="color:${statusColor};">${getC(d.状态) || '未知'}</span></div>`;
                if (d.进度) html += `<div class="md-row"><span class="md-label">执行进度:</span> <span class="md-val" style="color:var(--sys-cyan);">${getC(d.进度)}</span></div>`;
                if (d.时限) html += `<div class="md-row"><span class="md-label">时间限制:</span> <span class="md-val" style="color:var(--sys-red);">${d.时限}</span></div>`;
                html += `<div class="md-desc"><strong style="color:var(--sys-cyan)">[任务简报]</strong><br>${d.描述 || '无描述'}</div>`;
                if (d.目标 && Object.keys(d.目标).length > 0) { html += `<div class="md-desc"><strong style="color:var(--sys-cyan)">[执行目标]</strong><br>`; for (var tk in d.目标) { html += `- ${tk} [${d.目标[tk]}]<br>`; } html += `</div>`; }
                if (d.奖励) html += `<div class="md-desc" style="border-color:var(--sys-green);"><strong style="color:var(--sys-green);">[任务奖励]</strong><br>${d.奖励}</div>`;
                if (d.失败惩罚) html += `<div class="md-desc" style="border-color:var(--sys-red);"><strong style="color:var(--sys-red);">[失败惩罚]</strong><br>${d.失败惩罚}</div>`;
            }
            else if (info.type === 'achieve') {
                var d = info.data; title = d.名称 || info.name; icon = 'fa-trophy';
                html += `<div class="md-row"><span class="md-label">达成状态:</span> <span class="md-val" style="color:var(--q-epic);">已达成</span></div><div class="md-row"><span class="md-label">达成时间:</span> <span class="md-val">${d.达成时间 || '未知'}</span></div><div class="md-desc"><strong style="color:var(--sys-cyan)">[成就说明]</strong><br>${d.描述 || '无描述'}</div>`;
                if (d.奖励) html += `<div class="md-desc" style="border-color:var(--sys-green);"><strong style="color:var(--sys-green);">[成就奖励]</strong><br>${d.奖励}</div>`;
            }
            else if (info.type === 'relation') {
                var d = info.data; title = `羁绊档案 - ${info.name}`; icon = 'fa-project-diagram'; var getC = (v) => SysVarApi.isMvuTupleLeafValue(v) ? v[0] : v;
                html += `<div class="md-row"><span class="md-label">信赖:</span> <span class="md-val" style="color:var(--sys-green);">${formatNum(getC(d.信赖) || 0)}</span></div><div class="md-row"><span class="md-label">恋慕:</span> <span class="md-val" style="color:#ec4899;">${formatNum(getC(d.恋慕) || 0)}</span></div><div class="md-desc">信赖: 代表安全感、认同感与心理防御的卸下程度。<br>恋慕: 代表性张力、浪漫渴望与荷尔蒙冲动。</div>`;
            }
            else if (info.type === 'shop_item') {
                var d = info.data; title = info.name || '未知商品'; icon = getSysIcon(info.name, d.标签); var getC = (v) => SysVarApi.isMvuTupleLeafValue(v) ? v[0] : v; var qClass = getQClass(d.品质);
                html += `<div class="md-row"><span class="md-label">品质评级:</span> <span class="md-val ${qClass}">[${getC(d.品质)||'普通'}]</span></div><div class="md-row"><span class="md-label">兑换价格:</span> <span class="md-val" style="color:var(--sys-accent); font-weight:bold;"><i class="fas fa-coins"></i> ${formatNum(getC(d.价格) || 0)} 源质点</span></div>`;
                if (d.标签 && d.标签.length > 0) { html += `<div class="md-row" style="border:none;"><span class="md-label" style="margin-top:2px;">商品标签:</span><div style="flex:1;">`; d.标签.forEach(function(t) { html += `<span class="md-tag">${t}</span>`; }); html += `</div></div>`; }
                html += `<div class="md-desc"><strong style="color:var(--sys-cyan)">[商品描述]</strong><br>${d.描述 || '无描述'}</div>`;
                if (d.属性 && Object.keys(d.属性).length > 0) { html += `<div class="md-stats">`; for (var ak in d.属性) { html += `<div class="md-stat-item"><span>${ak}</span><span>${getC(d.属性[ak])>=0?'+':''}${formatNum(getC(d.属性[ak]))}</span></div>`; } html += `</div>`; }
            }
            if (html !== '') openModal(title, icon, html);
        } catch(e) { console.error("解析交互数据失败", e); }
    });
}

