                        <button id="panel-edit-btn" class="ctrl-btn edit-btn" title="开启/关闭底层修改模式"><i class="fas fa-magic"></i></button>
                        <button id="panel-pin-btn" class="ctrl-btn" title="固定面板"><i class="fas fa-thumbtack"></i></button>
