                if (window.tavern_events) eventOn(tavern_events.MESSAGE_RECEIVED, updatePanelData);
                if (window.Mvu && window.Mvu.events) eventOn(window.Mvu.events.VARIABLE_UPDATE_ENDED, updatePanelData);
                if (window.tavern_events && window.tavern_events.VARIABLES_UPDATED) eventOn(tavern_events.VARIABLES_UPDATED, updatePanelData);
            }
        }, 100);
