}

function updatePanelData() {
    if ($('#system-panel-overlay').hasClass('active')) renderPanelData();
}

function bindPanelEvents() {
    var $triggerBtn = $('#system-trigger-btn'); var btnElement = $triggerBtn[0];
    var onPointerMove = function(e) {
        if (!isDragging) return;
        e.cancelable && e.preventDefault();
        var dx = e.screenX - pStartX, dy = e.screenY - pStartY;
        if (Math.abs(dx) > 5 || Math.abs(dy) > 5) { $triggerBtn.addClass('dragging'); hasMoved = true; }
        if ($triggerBtn.hasClass('dragging')) {
            var bounded = constrainFullyInViewport(pStartLeft + dx, pStartTop + dy, 42, 42);
            btnElement.style.setProperty('left', bounded.x + 'px', 'important');
            btnElement.style.setProperty('top', bounded.y + 'px', 'important');
            btnElement.style.setProperty('right', 'auto', 'important');
            btnElement.style.setProperty('bottom', 'auto', 'important');
            btnElement.style.setProperty('transform', 'none', 'important');
        }
    };
    var onPointerUp = function(e) {
        var win = btnElement.ownerDocument.defaultView || window;
        win.removeEventListener('pointermove', onPointerMove); win.removeEventListener('pointerup', onPointerUp); win.removeEventListener('pointercancel', onPointerUp);
        if (btnElement.releasePointerCapture) try { btnElement.releasePointerCapture(e.pointerId); } catch(err) {}
        if ($triggerBtn.hasClass('dragging')) {
            var rect = btnElement.getBoundingClientRect();
            localStorage.setItem('system-trigger-btn-position', JSON.stringify({ left: rect.left, top: rect.top }));
            localStorage.setItem('system-trigger-btn-user-dragged', 'true');
            setTimeout(function() { $triggerBtn.removeClass('dragging'); hasMoved = false; }, 50);
        } else if (e.type === 'pointerup') {
            $('#system-panel-overlay').hasClass('active') ? closeSystemPanel() : openSystemPanel();
        }
        isDragging = false;
    };
    btnElement.addEventListener('pointerdown', function(e) {
        if (e.button !== 0 && e.pointerType === 'mouse') return;
        e.cancelable && e.preventDefault(); e.stopPropagation();
        isDragging = true; hasMoved = false;
        pStartX = e.screenX; pStartY = e.screenY;
        var rect = btnElement.getBoundingClientRect();
        pStartLeft = rect.left; pStartTop = rect.top;
        if (btnElement.setPointerCapture) try { btnElement.setPointerCapture(e.pointerId); } catch(err) {}
        var win = btnElement.ownerDocument.defaultView || window;
        win.addEventListener('pointermove', onPointerMove); win.addEventListener('pointerup', onPointerUp); win.addEventListener('pointercancel', onPointerUp);
    });

    $('#system-panel-overlay').on('click', function(e) { if (e.target.id === 'system-panel-overlay' && !isPinned) closeSystemPanel(); });
    $('#panel-edit-btn').on('click', function(e) {
        e.stopPropagation(); window.isSysEditMode = !window.isSysEditMode;
        $(this).toggleClass('active', window.isSysEditMode);
        $('.sys-header, .sys-title').toggleClass('edit-mode-active', window.isSysEditMode);
        $('.sys-title').html(window.isSysEditMode ? '万界终端 <span style="font-size:10px; border:1px solid currentColor; border-radius:3px; padding:0 3px; margin-left:2px; font-weight:normal;">[覆写]</span>' : '万界旅行终端');
    });
    $('#panel-close-btn').on('click', closeSystemPanel);
    $('#panel-pin-btn').on('click', function(e) {
        e.stopPropagation(); isPinned = !isPinned;
        $(this).toggleClass('pinned', isPinned);
        $('#system-panel-overlay').toggleClass('pinned', isPinned);
    });
    $('#sys-modal-close').on('click', closeModal);
    $('#sys-detail-modal').on('click', function(e) { if (e.target.id === 'sys-detail-modal') closeModal(); });
    $('.nav-item').on('click', function() {
        $('.nav-item').removeClass('active'); $(this).addClass('active');
        var targetId = $(this).data('target');
        $('.tab-pane').removeClass('active'); $('#' + targetId).addClass('active');
    });

    var resizeTimer;
    $(window).on('resize.systemPanel', function () {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(function () {
            if (localStorage.getItem('system-trigger-btn-user-dragged') === 'true') {
                var posStr = localStorage.getItem('system-trigger-btn-position');
                if(posStr) {
                    var pos = JSON.parse(posStr);
                    var bounded = constrainFullyInViewport(pos.left, pos.top, 42, 42);
                    btnElement.style.setProperty('left', bounded.x + 'px', 'important');
                    btnElement.style.setProperty('top', bounded.y + 'px', 'important');
                }
            } else { window.resetSystemButtonPosition(); }
        }, 250);
    });
}

function openSystemPanel() { renderPanelData(); $('#system-panel-overlay').addClass('active'); }
function closeSystemPanel() { $('#system-panel-overlay').removeClass('active'); closeModal(); }
function cleanupSystemPanel() {
    var btn = document.getElementById('system-trigger-btn');
    if (btn) btn.removeEventListener('pointerdown', null);
    $(window).off('resize.systemPanel');
    $('#system-trigger-btn, #system-panel-overlay, #system-panel-styles').remove();
    isDragging = false; hasMoved = false; isPinned = false; window.isSysEditMode = false;
    try { delete (window.parent || window).__万界系统面板_loaded__; } catch(e) {}
}

if (typeof window !== 'undefined') { window.initializeSystemPanel = initializeSystemPanel; window.cleanupSystemPanel = cleanupSystemPanel; window.openSystemPanel = openSystemPanel; window.closeSystemPanel = closeSystemPanel; }
$(function() {
    (async function() {
        var MAX_WAIT_TIME = 30000; var CHECK_INTERVAL = 100; var startTime = Date.now();
        try {
            while (typeof waitGlobalInitialized !== 'function') {
                if (Date.now() - startTime > MAX_WAIT_TIME) { initializeSystemPanel(); return; }
                await new Promise(function(resolve) { setTimeout(resolve, CHECK_INTERVAL); });
            }
            await waitGlobalInitialized('Mvu'); initializeSystemPanel();
        } catch (e) { try { initializeSystemPanel(); } catch (e2) {} }
    })();
});
$(document).on('keydown', function(e) { if (e.key === 'Escape' && $('#system-panel-overlay').hasClass('active') && !isPinned) { if ($('#sys-detail-modal').hasClass('active')) closeModal(); else closeSystemPanel(); } });
$(window).on('unload', cleanupSystemPanel);
